<script setup lang="ts">
import {ref,computed,nextTick,onBeforeUnmount} from 'vue'
import {newId} from '../../ids'
const props=defineProps<{disabled?:boolean;transfer?:boolean;canUp?:boolean;canDown?:boolean}>()
const emit=defineEmits<{(e:'action',action:string):void}>()
const open=ref(false),trigger=ref<HTMLButtonElement>(),menu=ref<HTMLElement>(),top=ref(0),left=ref(0),id='entry-actions-'+newId()
const options=computed(()=>[{key:'edit',label:'编辑卡片'},{key:'duplicate',label:'复制卡片'},{key:'copy',label:'复制到其他文章',disabled:!props.transfer},{key:'move',label:'移动到其他文章',disabled:!props.transfer},{key:'up',label:'向上移动',disabled:!props.canUp},{key:'down',label:'向下移动',disabled:!props.canDown},{key:'delete',label:'删除卡片'}])
function close(focus=true){open.value=false;document.removeEventListener('pointerdown',outside,true);window.removeEventListener('resize',position);window.removeEventListener('scroll',position,true);if(focus)trigger.value?.focus()}
function outside(e:Event){if(!menu.value?.contains(e.target as Node)&&!trigger.value?.contains(e.target as Node))close(false)}
function position(){const r=trigger.value?.getBoundingClientRect();if(!r)return;const w=menu.value?.offsetWidth||220,h=menu.value?.offsetHeight||330;left.value=Math.max(8,Math.min(r.right-w,window.innerWidth-w-8));top.value=Math.max(8,Math.min(r.bottom+6,window.innerHeight-h-8))}
async function toggle(){if(open.value){close();return}open.value=true;await nextTick();position();document.addEventListener('pointerdown',outside,true);window.addEventListener('resize',position);window.addEventListener('scroll',position,true);items()[0]?.focus()}
function items(){return Array.from(menu.value?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')||[])}
function key(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close()}else if(e.key==='Tab'){close(false)}else if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const all=items(),i=all.indexOf(document.activeElement as HTMLButtonElement);all[e.key==='Home'?0:e.key==='End'?all.length-1:(i+(e.key==='ArrowDown'?1:-1)+all.length)%all.length]?.focus()}}
function select(action:string){close();emit('action',action)}
onBeforeUnmount(()=>close(false))
</script>
<template><button ref="trigger" type="button" class="entry-menu-trigger quiet" aria-label="卡片操作" aria-haspopup="menu" :aria-expanded="open" :aria-controls="open?id:undefined" :disabled="disabled" @click.stop="toggle" @mousedown.stop @keydown.down.prevent="!open&&toggle()">···</button><Teleport to="body"><div v-if="open" :id="id" ref="menu" class="entry-action-menu" role="menu" aria-label="卡片操作菜单" :style="{top:top+'px',left:left+'px'}" @keydown="key" @mousedown.stop @click.stop><button v-for="option in options" :key="option.key" role="menuitem" type="button" :disabled="option.disabled||disabled" :class="{'entry-danger':option.key==='delete','entry-menu-divider':['up','delete'].includes(option.key)}" @click="select(option.key)">{{option.label}}</button></div></Teleport></template>
<style>.entry-menu-trigger{min-width:40px;min-height:40px;padding:4px 10px!important;line-height:1;font-size:24px!important;letter-spacing:1px}.entry-action-menu{position:fixed;z-index:1200;width:min(220px,calc(100vw - 16px));max-height:calc(100dvh - 16px);overflow-y:auto;box-sizing:border-box;padding:6px;border:1px solid var(--ui-line);border-radius:12px;background:var(--ui-card);color:var(--ui-ink);box-shadow:0 8px 28px color-mix(in srgb,var(--ui-ink) 18%,transparent)}.entry-action-menu button{display:block;width:100%;text-align:left;min-height:40px;background:transparent;color:var(--ui-ink);border:0;border-radius:6px;font-size:13px;padding:8px 12px}.entry-action-menu button:hover,.entry-action-menu button:focus-visible{background:var(--ui-card);outline:2px solid var(--ui-accent);outline-offset:-2px}.entry-action-menu button:disabled{opacity:.4}.entry-action-menu .entry-danger{color:var(--ui-danger,#b53030)}.entry-action-menu .entry-menu-divider{border-top:1px solid var(--ui-line);border-radius:0;margin-top:4px}</style>
